<script>
  const modules = [
    { id:'mail', icon:'✉', name:'Mail', plain:'信件積木', color:'#42766b', description:'讀信、整理信、寫草稿和寄信。', scopes:['mail.read','mail.write','mail.send'], settings:['帳號與連線','讀取 / 整理 / 寄送','退訂政策'], permissions:['OAuth 信件權限','Apple app-specific password'], path:'mail/module.ts', layers:[['工具入口','mail/mcp/','把問題變成有格式的操作。'],['工作規則','mail/services/','檢查政策、帳號與重複寄送。'],['共同語言','mail/domain/','定義信件、附件、錯誤與介面。'],['Apple 連接器','mail/icloud/','IMAP 讀取 / 整理；SMTP 寄送；MIME 解析。'],['記事本','mail/storage/','儲存政策與寄送紀錄；不盲目重試未知結果。']] },
    { id:'calendar', icon:'▦', name:'Calendar', plain:'日曆積木', color:'#92713c', description:'看行程、修改活動、邀請和分享。', scopes:['calendar.read','calendar.write','calendar.schedule','calendar.share'], settings:['CalDAV 連線','讀取 / 修改','邀請 / 分享'], permissions:['OAuth 日曆權限','Apple app-specific password'], path:'calendar/module.ts', layers:[['工具入口','calendar/mcp/','驗證日曆命令與參數。'],['工作規則','calendar/services/','權限、操作紀錄、同步與失敗復原。'],['共同語言','calendar/domain/','iCalendar 編碼、日期、時區與有限的重複規則。'],['Apple 連接器','calendar/icloud/','CalDAV 探索與請求；核對 ETag 等版本證據。'],['記事本','calendar/storage/','加密、綁定帳號的操作與同步紀錄。']] },
    { id:'photos', icon:'▧', name:'Photos', plain:'照片積木', color:'#77649c', description:'看相片與相簿，預覽後再整理或刪除。', scopes:['photos.read','photos.write','photos.delete'], settings:['Mac 相片圖庫','圖庫存取與 Full Access','整理 / 刪除','Shared Album provider session'], permissions:['OAuth 照片權限','Mac 圖庫檔案存取','原生 Helper 的 Photos 授權','獨立的 Photos web session（候選路徑）'], path:'photos/module.ts', layers:[['工具入口','photos/module.ts','宣告工具與 read / write / delete 權限。'],['工作規則','photos/service.ts','prepare → 明確確認 → apply；檢查計畫與目前資料。'],['本機連接器','photos/provider.ts','Bun 呼叫 osxphotos 讀本機同步圖庫。'],['原生操作','Photos Swift / PhotoKit helper','處理需要原生 API 的操作與 Apple 授權提示。'],['另一條路','photos/shared-albums.ts','Shared Album web provider 使用獨立 session；驗收分開追蹤。'],['記事本','Photos tables in application SQLite','記錄計畫、操作與 review；本機成功不等於雲端同步。']] }
  ];
  let selected = $state('mail');
  let enabled = $state({mail:true, calendar:false, photos:false});
  let cleanup = $state({mail:false, calendar:false, photos:false});
  let currentStep = $state(0);
  const steps = [
    ['你說一句話','「幫我找昨天的信。」','Assistant 把需求轉成 mail 工具呼叫。'],
    ['進入同一扇門','/icloud/mcp','HTTP host 接收請求，驗證 bearer token。'],
    ['確認你是誰','ownerId + accountId','auth 驗證身分；request-local context 帶著這個帳號。'],
    ['找積木、檢查鑰匙','ModuleRuntime + MCP host','工具必須啟用，而且 token 必須具備工具要求的 scopes。'],
    ['積木做自己的工作','Mail → service → IMAP','模組再次核對目前政策與帳號憑證，呼叫 provider。'],
    ['帶結果回來','Provider → module → MCP → Assistant','返回實際資料或錯誤；未知的寫入結果保留 unknown。']
  ];
  const shared = [
    ['server/','大門與接線','application.ts 組合模組；http.ts 接請求；lifecycle.ts 管理收尾。'],
    ['modules/','積木名冊','runtime.ts 登記工具、scopes 與 start / dispose；context.ts 帶入請求身分。'],
    ['mcp/','共同櫃台','只認工具契約；不必懂每一種信件或照片操作。'],
    ['auth/','驗身分與發鑰匙','Passkey、OAuth、帳號選擇、同意與 bearer 驗證。'],
    ['admin/','控制面板','私有 owner setup、帳號、能力政策與 Connections 管理。'],
    ['storage/','上鎖的櫃子','SQLite 儲存 owner 和加密憑證；master key 的保管另有邊界。'],
    ['observability/','工作紀錄員','記錄有界操作狀態；不把秘密放進日誌。'],
    ['plugin/','連線說明包','產生設定好的 client artifact；不夾帶 server secrets。'],
    ['ui/ + i18n/','外觀與文字','共用頁面樣式、元件與語言資源。']
  ];
  const proposed = [
    ['identity','這是誰？','id、version、相容的 host 版本'],
    ['configuration','需要哪些設定？','schema、驗證、admin UI contribution'],
    ['capabilities','會提供什麼？','tools、scopes、依賴與最小權限'],
    ['lifecycle','怎麼加入與離開？','prepare / start / block / drain / dispose'],
    ['permissions','鑰匙怎麼收回？','權限 owner、共享使用者、撤銷方式、回讀檢查'],
    ['state','什麼要留下？','schema、migration、audit 與 unknown 操作復原']
  ];
  let active = $derived(modules.find(m=>m.id===selected));
  let activeModules = $derived(modules.filter(m=>enabled[m.id]));
  function toggle(id) { const next = !enabled[id]; enabled={...enabled,[id]:next}; cleanup={...cleanup,[id]:!next}; }
</script>

<svelte:head><title>iCloud · 一盒可以開關的積木</title><meta name="description" content="An illustrated source-grounded guide to iCloud plugin architecture and its proposed module lifecycle." /></svelte:head>

<div class="guide">
  <header class="topbar"><a href="#start" class="brand">◈ iCloud <span>architecture atlas</span></a><span class="edition">SOURCE SNAPSHOT · 2026.10.06</span></header>
  <main>
    <section id="start" class="hero">
      <div class="eyebrow">從一張圖，到每一顆積木</div>
      <h1>一盒積木。<br/>想用哪顆，<em>就開哪顆。</em></h1>
      <p class="lead">信件、日曆、照片各做自己的事。<br/>共用一個服務、一扇 AI 入口、一個管理面板。</p>
      <div class="legend"><span class="badge current">● 現有程式</span><span class="badge future">◇ 未來設計</span><span class="badge attention">◌ 還要你幫忙清理</span></div>
      <div class="hero-blocks" aria-label="Three feature building blocks"><div class="brick mail">✉<b>Mail</b><small>信件</small></div><div class="brick calendar">▦<b>Calendar</b><small>日曆</small></div><div class="brick photos">▧<b>Photos</b><small>照片</small></div></div>
      <div class="promise">我們的目標：關掉積木，也收回它的鑰匙。<small>這裡是架構解說與設計示範；頁面開關不會操作實際帳號、服務或權限。</small></div>
    </section>
    <nav class="jump" aria-label="Guide sections"><a href="#map">01 大圖</a><a href="#journey">02 一次請求</a><a href="#inside">03 拆開積木</a><a href="#play">04 試開關</a><a href="#keys">05 收回鑰匙</a><a href="#build">06 怎麼蓋</a><a href="#evidence">07 證據</a></nav>

    <section id="map">
      <div class="section-label">01 / THE BIG PICTURE <span class="badge current">現有程式</span></div>
      <h2>先看整個玩具屋。</h2><p class="intro">外面的人走 AI 大門。主人走管理大門。裡面共用同一組基礎設施。</p>
      <div class="architecture">
        <div class="entrances"><div class="node"><span>你 + Assistant</span><strong>Public MCP / OAuth</strong><small>token、同意、工具呼叫</small></div><div class="node"><span>你 + 瀏覽器</span><strong>Private Admin</strong><small>owner 身分、設定、模組政策</small></div></div>
        <div class="connectors">↓ <span>兩種入口，各自有存取檢查</span> ↓</div>
        <div class="host"><div class="host-title">一個 Bun / TypeScript application <small>server/application.ts 負責接線</small></div><div class="foundation"><span>Auth<br/><small>驗身分</small></span><span>ModuleRuntime<br/><small>登記積木</small></span><span>MCP host<br/><small>派工作</small></span></div><div class="module-row">{#each modules as m}<div style:--module-color={m.color}><b>{m.icon} {m.name}</b><small>工具 + 規則 + 連接器 + 狀態</small></div>{/each}</div><div class="foundation bottom"><span>Owner / secret store</span><span>Operation monitor</span><span>HTTP lifecycle</span></div></div>
        <div class="connectors">↓ <span>由各模組負責連接外面的資料</span> ↓</div>
        <div class="providers"><div>✉<b>Apple Mail</b><small>IMAP / SMTP</small></div><div>▦<b>Apple Calendar</b><small>CalDAV</small></div><div>▧<b>Mac Photos / provider</b><small>osxphotos · PhotoKit · web session 候選</small></div></div>
      </div>
      <div class="note">「一個服務」不代表所有東西都在同一個 process。Photos 可以呼叫 Python / Swift helper；服務仍提供同一個 MCP 入口。</div>
      <h3>誰負責哪件事？</h3><div class="table-wrap"><table><thead><tr><th>位置</th><th>像什麼</th><th>實際做法</th></tr></thead><tbody>{#each shared as row}<tr><td><code>{row[0]}</code></td><td>{row[1]}</td><td>{row[2]}</td></tr>{/each}</tbody></table></div>
    </section>

    <section id="journey">
      <div class="section-label">02 / FOLLOW ONE REQUEST <span class="badge current">現有程式</span></div><h2>一句話，怎麼變成工作？</h2><p class="intro">點一站，跟著信件請求走。工具看得見，不代表你已有使用它的鑰匙。</p>
      <div class="journey-track">{#each steps as step,i}<button class:chosen={currentStep===i} onclick={()=>currentStep=i} aria-pressed={currentStep===i}><span>{i+1}</span>{step[0]}</button>{/each}</div>
      <div class="journey-detail" aria-live="polite"><div class="big-number">0{currentStep+1}</div><div><h3>{steps[currentStep][1]}</h3><p>{steps[currentStep][2]}</p></div></div>
      <div class="equation"><span>積木已啟用</span><b>＋</b><span>主人政策允許</span><b>＋</b><span>這個 token 有 scope</span><b>＋</b><span>provider 可用</span><b>→</b><strong>才能做事</strong></div>
      <div class="split"><div class="card"><h3>每次都帶自己的名牌。</h3><p><code>ownerId + accountId</code> 放在 request-local context，模組拿指定帳號的憑證。</p><div class="mini-flow"><span>Connection A → 帳號 A</span><span>Connection B → 帳號 B</span></div><small>不靠一個全域「目前帳號」來切換所有人的請求。</small></div><div class="card"><h3>工具清單 ≠ 使用權限。</h3><p>現有 MCP discovery 列出政策允許的工具。實際呼叫還會檢查 token scopes；缺少時要求重新同意。</p><div class="mini-flow"><span>看見工具 → 要求同意 → token 有 scope</span></div><small>加模組不會偷偷擴大原有 token 或 consent。</small></div></div>
    </section>

    <section id="inside">
      <div class="section-label">03 / OPEN THE BLOCKS <span class="badge current">現有程式</span></div><h2>拆開一顆積木。</h2><p class="intro">每顆都有工具入口、工作規則、連接資料的方法，以及自己的記事本。</p>
      <div class="tabs" aria-label="Select a module">{#each modules as m}<button onclick={()=>selected=m.id} class:chosen={selected===m.id} aria-pressed={selected===m.id}>{m.icon} {m.name}</button>{/each}</div>
      <div class="module-detail" style:--module-color={active.color}><div class="module-heading"><div><span class="eyebrow">{active.path}</span><h3>{active.plain}</h3><p>{active.description}</p></div><span class="module-icon">{active.icon}</span></div><div class="layers">{#each active.layers as layer,i}<div class="layer"><span class="layer-number">{i+1}</span><div><b>{layer[0]}</b><code>{layer[1]}</code></div><p>{layer[2]}</p></div>{/each}</div><div class="scope-list">{#each active.scopes as scope}<code>{scope}</code>{/each}</div></div>
      <div class="split"><div class="card"><h3>現有積木插頭</h3><div class="plug"><code>RuntimeModule</code><span>id</span><span>scopes</span><span>tools</span><span>start?</span><span>dispose?</span></div><p>啟動前 register。禁止重複 id、scope、tool；名稱要屬於自己的 namespace。</p><small>目前沒有通用的 config UI、權限 cleanup 或個別模組熱卸載契約。</small></div><div class="card"><h3>現在的開關，到哪一層？</h3><div class="status-line"><b>✓</b><span>政策改變 → 工具 discovery / 後續 dispatch 改變</span></div><div class="status-line"><b>◇</b><span>模組加入 / 移除 → 仍在 application composition 明確接線</span></div><div class="status-line"><b>◇</b><span>dispose → 目前是整個 runtime 的收尾，不是單顆熱拔除</span></div></div></div>
      <div class="table-wrap"><table><thead><tr><th>積木</th><th>現有接線</th><th>資料路徑</th><th>證據邊界</th></tr></thead><tbody><tr><td>Mail</td><td>composition 必定註冊</td><td>帳號憑證 → IMAP / SMTP</td><td>此頁沒有重測 live mailbox</td></tr><tr><td>Calendar</td><td>必定註冊；預設政策關閉</td><td>帳號憑證 → CalDAV</td><td>source 與專屬 production evidence 分開</td></tr><tr><td>Photos</td><td>有 settings.photos 才註冊</td><td>Mac 圖庫 / native helper；另有 web provider source</td><td>本機 readback、原生寫入、雲端與遠端 client 各自驗收</td></tr><tr><td>Drive / Contacts</td><td>尚未接入此 composition</td><td>待定</td><td>未來方向，不畫成已完成</td></tr><tr><td>HomeKit</td><td>未接入此 composition</td><td>另外的實驗 / 規劃</td><td>不等於目前服務已支援</td></tr></tbody></table></div>
    </section>

    <section id="play">
      <div class="section-label">04 / TRY THE FUTURE <span class="badge future">未來設計示範</span></div><h2>你選積木。服務跟著變。</h2><p class="intro">試著開啟 Photos，再關掉。看看設定頁、背景工作和鑰匙怎麼一起改變。</p>
      <div class="simulator"><div class="switches"><h3>模組開關</h3>{#each modules as m}<div class="switch-row"><div><b>{m.icon} {m.name}</b><small>{enabled[m.id]?'已啟用（示範）':cleanup[m.id]?'已停用 · 清理待完成':'未啟用（示範）'}</small></div><button class="switch" class:on={enabled[m.id]} role="switch" aria-label={'啟用 '+m.name} aria-checked={enabled[m.id]} onclick={()=>toggle(m.id)}><span></span></button></div>{/each}<small class="sim-label">僅改變這個頁面的示範。<br/>初始值不是目前安裝的狀態。</small></div><div class="sim-result" aria-live="polite"><div class="preview-panel"><span class="eyebrow">ADMIN 將顯示</span><div class="admin-tabs"><span>總覽</span><span>模組</span><span>權限清理</span>{#each activeModules as m}<b>{m.name} 設定</b>{/each}</div>{#each activeModules as m}<div class="config-row"><b>{m.name}</b><span>{m.settings.join(' · ')}</span></div>{/each}{#if activeModules.length===0}<p>只留下共用設定與清理頁。功能設定頁已移除。</p>{/if}</div><div class="preview-panel"><span class="eyebrow">BACKGROUND 將載入</span><div class="worker-list"><span class="core-worker">共同 Host</span>{#each activeModules as m}<span>{m.icon} {m.name} resources</span>{/each}</div><p>{activeModules.length} 顆功能積木，提供各自的 tools 與 provider resources。</p></div><div class="preview-panel"><span class="eyebrow">權限與清理</span>{#each modules as m}{#if enabled[m.id]}<div class="permission-row"><b>{m.name}</b><span>{m.permissions.join(' · ')}</span></div>{:else if cleanup[m.id]}<div class="cleanup-row"><b>◌ {m.name} 清理待完成</b><p>新工作已封鎖；示範假設收尾已完成。需再核對 OAuth、共享憑證與外部授權。</p><button class="secondary" onclick={()=>cleanup={...cleanup,[m.id]:false}}>模擬：已驗證清理完成</button></div>{/if}{/each}{#if !modules.some(m=>enabled[m.id]||cleanup[m.id])}<p>沒有功能權限需求，也沒有未完成的清理。</p>{/if}</div></div></div>
      <div class="note">關掉功能設定頁後，仍保留「權限清理」與 audit / recovery 入口。否則你會看不到還沒收回的鑰匙。</div>
    </section>

    <section id="keys">
      <div class="section-label">05 / NO KEYS LEFT BEHIND <span class="badge future">目標與限制</span></div><h2>不用了，就把鑰匙收好。</h2><p class="intro">一顆積木可能有好幾把鑰匙。關掉它，要逐把檢查。</p>
      <div class="key-diagram"><div><span>1</span><b>服務政策</b><small>我們准不准做？</small></div><div><span>2</span><b>OAuth 同意 / token</b><small>這個 connection 准不准做？</small></div><div><span>3</span><b>Provider 憑證 / session</b><small>Apple 那邊准不准進？</small></div><div><span>4</span><b>Mac 系統權限</b><small>這個 app 能不能看圖庫？</small></div></div>
      <div class="table-wrap"><table><thead><tr><th>鑰匙</th><th>關掉模組時的目標</th><th>怎麼知道真的收回？</th><th>目前 / 外部限制</th></tr></thead><tbody><tr><td>Operator policy</td><td>立即禁止新呼叫、停止列出工具</td><td>舊 client 再呼叫也被拒絕</td><td>現有 runtime 已有政策 gate；完整生命週期仍待實作</td></tr><tr><td>OAuth scopes、consent、tokens</td><td>撤銷 / 收窄此模組的 grants，失效快取</td><td>舊 token 不能使用或 refresh 回此能力</td><td>現有政策開關不改寫舊 grants；混合 scopes 的 token 需要設計安全重發 / 重新同意</td></tr><tr><td>加密本機憑證 / provider session</td><td>刪除專屬 session；共用的先檢查還有誰在用</td><td>本機 custody 與實際 provider 狀態分別回讀</td><td>Mail / Calendar 可共用帳號密碼；刪本機 secret 不等於 Apple 撤銷</td></tr><tr><td>Apple app-specific password</td><td>不用且不再共用時，指引 owner 撤銷</td><td>Apple 帳號頁確認 + 後續存取檢查</td><td>不要關 Calendar 就把 Mail 還需要的密碼撤掉</td></tr><tr><td>Mac Photos / 檔案權限</td><td>提供系統設定清理步驟，完成後重新檢查</td><td>檢查精確 app / helper 的授權與存取狀態</td><td>權限按 app / helper 身分管理；無法假定一般服務可自動撤銷全部系統授權</td></tr><tr><td>背景資源與程式碼</td><td>drain → dispose → 停掉 worker</td><td>無新工作、無 owned worker / timer / watcher</td><td>dispose 不等於移除 JavaScript code；嚴格卸載可用獨立 worker / process 或受控重啟</td></tr></tbody></table></div>
      <div class="split"><div class="card lifecycle-card"><h3>開啟：先拿必要的鑰匙。</h3><ol class="timeline"><li><b>選積木</b><span>檢查依賴、版本與設定。</span></li><li><b>顯示它需要什麼</b><span>只列這顆積木的最小權限；owner 明確操作才要求。</span></li><li><b>授權與連線驗證</b><span>OAuth 與 provider / Mac 授權分開檢查。</span></li><li><b>啟動 resources</b><span>成功後才發佈功能；client 還要 refresh 工具清單。</span></li></ol><small>拒絕 / 失敗 → 保持不可用，顯示已部分建立的資源與清理工作。</small></div><div class="card lifecycle-card"><h3>關閉：先關門，再收尾。</h3><ol class="timeline"><li><b>封鎖新工作</b><span>立刻隱藏工具並拒絕 dispatch。</span></li><li><b>等已接受的工作收尾</b><span>不能假裝取消已送到 provider 的寫入；unknown 要保留。</span></li><li><b>釋放資源、收回權限</b><span>停 worker；撤銷專屬 grants / session；保護共用需求。</span></li><li><b>驗證清理結果</b><span>系統 / Apple 要 owner 操作時，保持「清理待完成」。</span></li></ol><small>只有全部可驗證項目完成，才顯示「已關閉且清理完成」。</small></div></div>
      <div class="state-machine" aria-label="Proposed lifecycle states"><span>OFF</span><b>→</b><span>準備 / 等授權</span><b>→</b><span class="state-on">ON</span><b>→</b><span>封鎖 / 收尾</span><b>→</b><span class="state-pending">CLEANUP REQUIRED</span><b>→</b><span>OFF · CLEAN</span></div><div class="note">Cleanup required 不是每次都需要；可自動完成時直接到 OFF · CLEAN。失敗 / unknown 不能被畫成完成。重新啟用也不能繞過未解決的寫入。</div>
      <h3>共享鑰匙，不能隨便剪掉。</h3><div class="shared-key"><span>Mail · ON</span><b>↘</b><div>同一帳號的 Apple 密碼<br/><small>仍有人需要 → 保留並標示依賴</small></div><b>↗</b><span>Calendar · OFF</span></div>
      <p class="sources-inline">系統權限邊界：<a href="https://support.apple.com/en-gb/guide/mac-help/mchl244f2895/mac" target="_blank" rel="noreferrer">Apple：管理 Mac Photos 存取</a> · <a href="https://developer.apple.com/documentation/xcode/resetting-access-to-protected-resources-in-macos" target="_blank" rel="noreferrer">Apple：開發時重設受保護資源存取</a>。這些是清理指引依據，並非本頁已執行清理。</p>
    </section>

    <section id="build">
      <div class="section-label">06 / THE BUILDING PLAN <span class="badge future">待實作</span></div><h2>接下來，需要哪些新積木？</h2><p class="intro">保留現有共享 host，補上模組控制器、設定插槽，以及權限清理帳本。</p>
      <div class="target-map"><div class="node"><strong>Module catalog / manifest</strong><small>描述工具、設定、依賴與權限</small></div><div class="connectors">↓</div><div class="target-controller"><b>Module controller</b><p>記錄想要的狀態 → 執行 enable / disable → 回讀實際狀態</p><div class="controller-parts"><span>Configuration registry</span><span>Permission coordinator</span><span>Lifecycle supervisor</span></div></div><div class="connectors">↓</div><div class="target-outputs"><div><b>Admin routes</b><small>只載入啟用模組的設定；清理頁一直在</small></div><div><b>MCP contributions</b><small>依實際 ready 狀態列工具與檢查呼叫</small></div><div><b>Module workers</b><small>啟用時啟動；關閉時收尾與釋放</small></div></div></div>
      <div class="table-wrap"><table><thead><tr><th>模組要交出</th><th>白話問題</th><th>建議契約內容</th></tr></thead><tbody>{#each proposed as row}<tr><td><code>{row[0]}</code></td><td>{row[1]}</td><td>{row[2]}</td></tr>{/each}</tbody></table></div>
      <div class="roadmap"><div><span>01</span><h3>把開關做真</h3><p>區分 desired / actual state，持久化每次轉換與失敗。</p></div><div><span>02</span><h3>讓畫面跟著變</h3><p>模組提供 configuration schema / UI；共用 host 掛載設定頁。</p></div><div><span>03</span><h3>關掉也要收鑰匙</h3><p>追蹤 grants、共享憑證、Mac 權限；清理待辦可以回來完成。</p></div><div><span>04</span><h3>確實卸載</h3><p>評估每模組 worker / process 或受控重啟；不假裝 import 能被撤回。</p></div></div>
      <h3>我們怎麼驗收？</h3><div class="table-wrap"><table><thead><tr><th>操作</th><th>看得見的結果</th></tr></thead><tbody><tr><td>開 Photos，拒絕授權</td><td>Photos 沒有 ready；不提供可用工具；無靜默授權重試</td></tr><tr><td>開 Photos，完成授權</td><td>設定頁出現；worker / tools ready；同一 connection 明確新 consent 後可讀取</td></tr><tr><td>關 Calendar，保留 Mail</td><td>Calendar 新呼叫失敗；Mail 仍可用；共用密碼保持可用並明確列原因</td></tr><tr><td>舊 token 再呼叫 / refresh</td><td>被關閉的能力不能恢復；其餘能力依新的授權方案保留</td></tr><tr><td>關閉途中有寫入</td><td>保留 accepted / unknown 紀錄，不盲目重試或當成取消</td></tr><tr><td>關閉途中重啟</td><td>恢復未完成 cleanup；預設封鎖新工作；不把中途狀態誤標為 clean</td></tr><tr><td>完成 Mac / Apple 清理</td><td>回讀實際狀態，才移除待辦；剩餘 grants / workers 可稽核</td></tr></tbody></table></div>
    </section>

    <section id="evidence">
      <div class="section-label">07 / WHAT WE KNOW</div><h2>圖很簡單。證據要分清楚。</h2><p class="intro">這是此 checkout 的程式架構，不是正在執行的版本或所有 provider 的能力保證。</p>
      <div class="evidence-ladder"><span>Source<br/><small>程式有這條路</small></span><b>→</b><span>Fixture<br/><small>測試資料通過</small></span><b>→</b><span>Local live<br/><small>真實本機回讀</small></span><b>→</b><span>Remote client<br/><small>真實連線能呼叫</small></span><b>→</b><span>Cloud / other device<br/><small>外部狀態另驗證</small></span></div>
      <div class="table-wrap"><table><thead><tr><th>狀態</th><th>這頁的意思</th></tr></thead><tbody><tr><td><span class="badge current">現有程式</span></td><td>以 composition / runtime / MCP host / 模組 source 為準；本次未更動 runtime 或測試 Apple 帳號。</td></tr><tr><td><span class="badge future">未來設計</span></td><td>來自本次需求：動態模組、動態 admin、最小授權與停用清理。完整機制還沒實作。</td></tr><tr><td><span class="badge attention">清理待完成</span></td><td>功能已阻擋，但外部撤銷或 readback 尚未完成；不能宣稱沒有殘留權限。</td></tr></tbody></table></div>
      <details><summary>想看程式？展開來源地圖</summary><p>以下相對於 <code>apps/icloud/src/</code>。此頁的 README 保存完整 evidence pointers。</p><div class="code-map"><code>server/application.ts</code><code>modules/runtime.ts + context.ts</code><code>mcp/server.ts</code><code>auth/README.md</code><code>admin/README.md + handler.ts</code><code>storage/owner-store.ts</code><code>mail/module.ts</code><code>calendar/module.ts</code><code>photos/module.ts + provider.ts + shared-albums.ts</code></div><p>部分舊 README 仍寫 Calendar 未實作，與目前 source / Calendar README 不符。本頁以現有接線與模組 source 為準，沒有沿用舊的部署版本敘述。</p></details>
    </section>
    <footer><b>小小一句話：</b>選你要的積木。只借需要的鑰匙。不用了，就關門、收尾、把鑰匙還回去。<span>iCloud architecture atlas · source + proposed design · 2026.10.06</span></footer>
  </main>
</div>

